1	//! Typed, provider-neutral decisions for a managed release pull request.
2	//!
3	//! This is deliberately pre-merge collaboration policy, rather than durable
4	//! release authority. The values name a narrow, credential-free observation
5	//! and the one forge mutation sequence that an executor may perform.
6	
7	use schemars::JsonSchema;
8	use serde::{Deserialize, Deserializer, Serialize};
9	
10	use crate::CommitSha;
11	
12	/// Explicit identity and presentation configuration for one managed release PR.
13	#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
14	#[serde(rename_all = "camelCase", deny_unknown_fields)]
15	pub struct ReleasePrConfigV1 {
16	    pub schema_version: u8,
17	    pub repository: String,
18	    pub base_branch: String,
19	    pub release_branch: String,
20	}
21	
22	impl ReleasePrConfigV1 {
23	    pub const SCHEMA_VERSION: u8 = 1;
24	
25	    pub fn new(
26	        repository: String,
27	        base_branch: String,
28	        release_branch: String,
29	    ) -> Result<Self, ReleasePrDecisionError> {
30	        validate_repository(&repository)?;
31	        validate_branch("base branch", &base_branch)?;
32	        validate_branch("managed release branch", &release_branch)?;
33	        Ok(Self {
34	            schema_version: Self::SCHEMA_VERSION,
35	            repository,
36	            base_branch,
37	            release_branch,
38	        })
39	    }
40	}
41	
42	impl<'de> Deserialize<'de> for ReleasePrConfigV1 {
43	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
44	    where
45	        D: Deserializer<'de>,
46	    {
47	        #[derive(Deserialize)]
48	        #[serde(rename_all = "camelCase", deny_unknown_fields)]
49	        struct Wire {
50	            schema_version: u8,
51	            repository: String,
52	            base_branch: String,
53	            release_branch: String,
54	        }
55	        let wire = Wire::deserialize(deserializer)?;
56	        if wire.schema_version != Self::SCHEMA_VERSION {
57	            return Err(serde::de::Error::custom(
58	                "unsupported release PR configuration schema version",
59	            ));
60	        }
61	        Self::new(wire.repository, wire.base_branch, wire.release_branch).map_err(serde::de::Error::custom)
62	    }
63	}
64	
65	/// A credential-free observation supplied by a forge adapter before planning.
66	#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
67	#[serde(rename_all = "camelCase", deny_unknown_fields)]
68	pub struct ReleasePrSnapshotV1 {
69	    pub schema_version: u8,
70	    pub repository: String,
71	    pub base_branch: String,
72	    pub base_commit: CommitSha,
73	    pub open_pull_requests: Vec<ReleasePrPullRequestV1>,
74	}
75	
76	impl ReleasePrSnapshotV1 {
77	    pub const SCHEMA_VERSION: u8 = 1;
78	
79	    pub fn new(
80	        repository: String,
81	        base_branch: String,
82	        base_commit: CommitSha,
83	        mut open_pull_requests: Vec<ReleasePrPullRequestV1>,
84	    ) -> Result<Self, ReleasePrDecisionError> {
85	        validate_repository(&repository)?;
86	        validate_branch("base branch", &base_branch)?;
87	        let mut numbers = open_pull_requests.iter().map(|pr| pr.number).collect::<Vec<_>>();
88	        numbers.sort_unstable();
89	        if numbers.windows(2).any(|pair| pair[0] == pair[1]) {
90	            return Err(ReleasePrDecisionError::DuplicatePullRequestNumber);
91	        }
92	        open_pull_requests.sort_by_key(|pr| pr.number);
93	        Ok(Self {
94	            schema_version: Self::SCHEMA_VERSION,
95	            repository,
96	            base_branch,
97	            base_commit,
98	            open_pull_requests,
99	        })
100	    }
101	}
102	
103	impl<'de> Deserialize<'de> for ReleasePrSnapshotV1 {
104	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
105	    where
106	        D: Deserializer<'de>,
107	    {
108	        #[derive(Deserialize)]
109	        #[serde(rename_all = "camelCase", deny_unknown_fields)]
110	        struct Wire {
111	            schema_version: u8,
112	            repository: String,
113	            base_branch: String,
114	            base_commit: CommitSha,
115	            open_pull_requests: Vec<ReleasePrPullRequestV1>,
116	        }
117	        let wire = Wire::deserialize(deserializer)?;
118	        if wire.schema_version != Self::SCHEMA_VERSION {
119	            return Err(serde::de::Error::custom(
120	                "unsupported release PR snapshot schema version",
121	            ));
122	        }
123	        Self::new(
124	            wire.repository,
125	            wire.base_branch,
126	            wire.base_commit,
127	            wire.open_pull_requests,
128	        )
129	        .map_err(serde::de::Error::custom)
130	    }
131	}
132	
133	/// One open pull request observed by a forge adapter.
134	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
135	#[serde(rename_all = "camelCase", deny_unknown_fields)]
136	pub struct ReleasePrPullRequestV1 {
137	    pub number: u64,
138	    pub head_repository: String,
139	    pub head_branch: String,
140	    /// A Git observation, not a policy choice: true exactly when this branch
141	    /// differs from the current base at a workflow path.
142	    pub workflow_delta_from_base: bool,
143	}
144	
145	/// A closed release-PR operation selected by Callisto.
146	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
147	#[serde(
148	    rename_all = "camelCase",
149	    rename_all_fields = "camelCase",
150	    tag = "kind",
151	    deny_unknown_fields
152	)]
153	#[non_exhaustive]
154	pub enum ReleasePrActionV1 {
155	    Noop {
156	        reason: ReleasePrNoopReasonV1,
157	    },
158	    Create {
159	        branch: String,
160	    },
161	    Update {
162	        pull_request_number: u64,
163	        branch: String,
164	    },
165	    Supersede {
166	        pull_request_number: u64,
167	        expected_branch: String,
168	        replacement_branch: String,
169	    },
170	}
171	
172	/// Why a release-PR run is intentionally mutation-free.
173	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
174	#[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
175	#[non_exhaustive]
176	pub enum ReleasePrNoopReasonV1 {
177	    NoPendingChangesets,
178	}
179	
180	/// Versioned output of managed release-PR policy derivation.
181	#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
182	#[serde(rename_all = "camelCase", deny_unknown_fields)]
183	pub struct ReleasePrDecisionV1 {
184	    pub schema_version: u8,
185	    pub config: ReleasePrConfigV1,
186	    pub snapshot: ReleasePrSnapshotV1,
187	    pub action: ReleasePrActionV1,
188	}
189	
190	impl ReleasePrDecisionV1 {
191	    pub const SCHEMA_VERSION: u8 = 1;
192	
193	    /// Derives the only permitted action from fresh workspace and forge facts.
194	    pub fn derive(
195	        has_pending_changesets: bool,
196	        config: &ReleasePrConfigV1,
197	        snapshot: &ReleasePrSnapshotV1,
198	    ) -> Result<Self, ReleasePrDecisionError> {
199	        if snapshot.repository != config.repository || snapshot.base_branch != config.base_branch {
200	            return Err(ReleasePrDecisionError::SnapshotIdentityMismatch);
201	        }
202	
203	        let mut eligible = Vec::new();
204	        for pr in &snapshot.open_pull_requests {
205	            let shape = managed_branch_shape(&config.release_branch, &pr.head_branch)?;
206	            if shape.is_some() {
207	                if pr.head_repository != config.repository {
208	                    return Err(ReleasePrDecisionError::ForeignManagedPullRequest {
209	                        number: pr.number,
210	                        repository: pr.head_repository.clone(),
211	                    });
212	                }
213	                eligible.push(pr);
214	            }
215	        }
216	        if eligible.len() > 1 {
217	            return Err(ReleasePrDecisionError::AmbiguousManagedPullRequests { count: eligible.len() });
218	        }
219	
220	        let action = if !has_pending_changesets {
221	            ReleasePrActionV1::Noop {
222	                reason: ReleasePrNoopReasonV1::NoPendingChangesets,
223	            }
224	        } else if let Some(pr) = eligible.first() {
225	            if pr.workflow_delta_from_base {
226	                ReleasePrActionV1::Supersede {
227	                    pull_request_number: pr.number,
228	                    expected_branch: pr.head_branch.clone(),
229	                    replacement_branch: format!("{}--{}", config.release_branch, snapshot.base_commit.as_str()),
230	                }
231	            } else {
232	                ReleasePrActionV1::Update {
233	                    pull_request_number: pr.number,
234	                    branch: pr.head_branch.clone(),
235	                }
236	            }
237	        } else {
238	            ReleasePrActionV1::Create {
239	                branch: config.release_branch.clone(),
240	            }
241	        };
242	        Ok(Self {
243	            schema_version: Self::SCHEMA_VERSION,
244	            config: config.clone(),
245	            snapshot: snapshot.clone(),
246	            action,
247	        })
248	    }
249	
250	    /// Rejects any post-decision forge state change before the executor mutates.
251	    pub fn verify_snapshot(&self, observed: &ReleasePrSnapshotV1) -> Result<(), ReleasePrDecisionError> {
252	        if observed != &self.snapshot {
253	            return Err(ReleasePrDecisionError::SnapshotChanged);
254	        }
255	        Ok(())
256	    }
257	}
258	
259	impl<'de> Deserialize<'de> for ReleasePrDecisionV1 {
260	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
261	    where
262	        D: Deserializer<'de>,
263	    {
264	        #[derive(Deserialize)]
265	        #[serde(rename_all = "camelCase", deny_unknown_fields)]
266	        struct Wire {
267	            schema_version: u8,
268	            config: ReleasePrConfigV1,
269	            snapshot: ReleasePrSnapshotV1,
270	            action: ReleasePrActionV1,
271	        }
272	        let wire = Wire::deserialize(deserializer)?;
273	        if wire.schema_version != Self::SCHEMA_VERSION {
274	            return Err(serde::de::Error::custom(
275	                "unsupported release PR decision schema version",
276	            ));
277	        }
278	        Ok(Self {
279	            schema_version: wire.schema_version,
280	            config: wire.config,
281	            snapshot: wire.snapshot,
282	            action: wire.action,
283	        })
284	    }
285	}
286	
287	/// Invalid or unsafe release-PR observations and policies.
288	#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error, miette::Diagnostic)]
289	#[non_exhaustive]
290	pub enum ReleasePrDecisionError {
291	    #[error("release PR repository `{repository}` is invalid")]
292	    #[diagnostic(
293	        code(E141),
294	        help("Use the exact GitHub owner/repository identity, for example `orin-dx/callisto`.")
295	    )]
296	    InvalidRepository { repository: String },
297	    #[error("release PR {kind} `{branch}` is not a safe Git branch name")]
298	    #[diagnostic(code(E142), help("Use a non-empty Git ref name without whitespace, control characters, `..`, `@{{`, or shell-sensitive prefixes."))]
299	    InvalidBranch { kind: &'static str, branch: String },
300	    #[error("release PR snapshot contains the same pull request number more than once")]
301	    #[diagnostic(
302	        code(E143),
303	        help("Refresh the forge snapshot and pass each open pull request exactly once.")
304	    )]
305	    DuplicatePullRequestNumber,
306	    #[error("release PR snapshot does not match the configured repository or base branch")]
307	    #[diagnostic(
308	        code(E144),
309	        help(
310	            "Collect the snapshot for the configured repository and base branch immediately before calling Callisto."
311	        )
312	    )]
313	    SnapshotIdentityMismatch,
314	    #[error("managed release PR #{number} comes from foreign repository `{repository}`")]
315	    #[diagnostic(
316	        code(E145),
317	        help("Do not treat a fork branch as Callisto-managed; close or rename the lookalike before retrying.")
318	    )]
319	    ForeignManagedPullRequest { number: u64, repository: String },
320	    #[error("found {count} open managed release PRs")]
321	    #[diagnostic(
322	        code(E146),
323	        help("Resolve the ambiguous managed PRs manually before running the release action again.")
324	    )]
325	    AmbiguousManagedPullRequests { count: usize },
326	    #[error("managed release branch `{branch}` has an invalid SHA suffix")]
327	    #[diagnostic(
328	        code(E147),
329	        help(
330	            "Use the canonical branch or the canonical branch followed by `--` and one lowercase forty-hex commit SHA."
331	        )
332	    )]
333	    MalformedManagedBranch { branch: String },
334	    #[error("release PR snapshot changed after Callisto made its decision")]
335	    #[diagnostic(
336	        code(E148),
337	        help("Re-run `callisto release-pr decide` with a fresh snapshot; no forge mutation was made.")
338	    )]
339	    SnapshotChanged,
340	}
341	
342	fn validate_repository(repository: &str) -> Result<(), ReleasePrDecisionError> {
343	    let mut parts = repository.split('/');
344	    let valid = matches!((parts.next(), parts.next(), parts.next()), (Some(owner), Some(name), None) if valid_repo_part(owner) && valid_repo_part(name));
345	    if valid {
346	        Ok(())
347	    } else {
348	        Err(ReleasePrDecisionError::InvalidRepository {
349	            repository: repository.to_string(),
350	        })
351	    }
352	}
353	
354	fn valid_repo_part(part: &str) -> bool {
355	    !part.is_empty()
356	        && part
357	            .bytes()
358	            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.'))
359	}
360	
361	fn validate_branch(kind: &'static str, branch: &str) -> Result<(), ReleasePrDecisionError> {
362	    let valid = !branch.is_empty()
363	        && !branch.starts_with('-')
364	        && !branch.starts_with('/')
365	        && !branch.ends_with('/')
366	        && !branch.contains("//")
367	        && !branch.contains("..")
368	        && !branch.contains("@{")
369	        && branch != "@"
370	        && branch
371	            .split('/')
372	            .all(|part| !part.starts_with('.') && !part.ends_with(".lock"))
373	        && branch.chars().all(|ch| {
374	            !ch.is_ascii_control() && !ch.is_whitespace() && !matches!(ch, '~' | '^' | ':' | '?' | '*' | '[' | '\\')
375	        });
376	    if valid {
377	        Ok(())
378	    } else {
379	        Err(ReleasePrDecisionError::InvalidBranch {
380	            kind,
381	            branch: branch.to_string(),
382	        })
383	    }
384	}
385	
386	fn managed_branch_shape(canonical: &str, branch: &str) -> Result<Option<()>, ReleasePrDecisionError> {
387	    if branch == canonical {
388	        return Ok(Some(()));
389	    }
390	    let Some(suffix) = branch.strip_prefix(&format!("{canonical}--")) else {
391	        return Ok(None);
392	    };
393	    if suffix.len() == 40
394	        && suffix
395	            .bytes()
396	            .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
397	    {
398	        Ok(Some(()))
399	    } else {
400	        Err(ReleasePrDecisionError::MalformedManagedBranch {
401	            branch: branch.to_string(),
402	        })
403	    }
404	}
