407	mod tests {
408	    use super::*;
409	
410	    fn sha() -> CommitSha {
411	        CommitSha::parse("0123456789abcdef0123456789abcdef01234567").unwrap()
412	    }
413	
414	    fn config() -> ReleasePrConfigV1 {
415	        ReleasePrConfigV1::new(
416	            "orin-dx/callisto".to_string(),
417	            "main".to_string(),
418	            "callisto/version-packages".to_string(),
419	        )
420	        .unwrap()
421	    }
422	
423	    fn snapshot(prs: Vec<ReleasePrPullRequestV1>) -> ReleasePrSnapshotV1 {
424	        ReleasePrSnapshotV1::new("orin-dx/callisto".to_string(), "main".to_string(), sha(), prs).unwrap()
425	    }
426	
427	    fn pr(number: u64, branch: &str, workflow_delta_from_base: bool) -> ReleasePrPullRequestV1 {
428	        ReleasePrPullRequestV1 {
429	            number,
430	            head_repository: "orin-dx/callisto".to_string(),
431	            head_branch: branch.to_string(),
432	            workflow_delta_from_base,
433	        }
434	    }
435	
436	    #[test]
437	    fn derives_create_when_no_managed_pr_exists() {
438	        let decision = ReleasePrDecisionV1::derive(true, &config(), &snapshot(vec![])).unwrap();
439	        assert_eq!(
440	            decision.action,
441	            ReleasePrActionV1::Create {
442	                branch: "callisto/version-packages".to_string()
443	            }
444	        );
445	        assert_eq!(decision.config, config());
446	    }
447	
448	    #[test]
449	    fn derives_update_for_one_canonical_or_replacement_pr() {
450	        for branch in [
451	            "callisto/version-packages",
452	            "callisto/REDACTED",
453	        ] {
454	            let decision =
455	                ReleasePrDecisionV1::derive(true, &config(), &snapshot(vec![pr(42, branch, false)])).unwrap();
456	            assert_eq!(
457	                decision.action,
458	                ReleasePrActionV1::Update {
459	                    pull_request_number: 42,
460	                    branch: branch.to_string()
461	                }
462	            );
463	        }
464	    }
465	
466	    #[test]
467	    fn action_variant_fields_serialize_as_camel_case() {
468	        let update = ReleasePrActionV1::Update {
469	            pull_request_number: 42,
470	            branch: "callisto/version-packages".to_string(),
471	        };
472	        let value = serde_json::to_value(&update).unwrap();
473	        assert_eq!(value["kind"], "update");
474	        assert_eq!(value["pullRequestNumber"], 42);
475	        assert!(value.get("pull_request_number").is_none());
476	
477	        let supersede = ReleasePrActionV1::Supersede {
478	            pull_request_number: 42,
479	            expected_branch: "callisto/version-packages".to_string(),
480	            replacement_branch: "callisto/version-packages--sha".to_string(),
481	        };
482	        let value = serde_json::to_value(&supersede).unwrap();
483	        assert_eq!(value["kind"], "supersede");
484	        assert_eq!(value["pullRequestNumber"], 42);
485	        assert_eq!(value["expectedBranch"], "callisto/version-packages");
486	        assert_eq!(value["replacementBranch"], "callisto/version-packages--sha");
487	    }
488	
489	    #[test]
490	    fn derives_deterministic_supersede_when_workflow_delta_is_observed() {
491	        let decision = ReleasePrDecisionV1::derive(
492	            true,
493	            &config(),
494	            &snapshot(vec![pr(42, "callisto/version-packages", true)]),
495	        )
496	        .unwrap();
497	        assert_eq!(
498	            decision.action,
499	            ReleasePrActionV1::Supersede {
500	                pull_request_number: 42,
501	                expected_branch: "callisto/version-packages".to_string(),
502	                replacement_branch: "callisto/REDACTED".to_string(),
503	            }
504	        );
505	    }
506	
507	    #[test]
508	    fn no_pending_changesets_is_noop_after_snapshot_validation() {
509	        let decision = ReleasePrDecisionV1::derive(
510	            false,
511	            &config(),
512	            &snapshot(vec![pr(42, "callisto/version-packages", true)]),
513	        )
514	        .unwrap();
515	        assert_eq!(
516	            decision.action,
517	            ReleasePrActionV1::Noop {
518	                reason: ReleasePrNoopReasonV1::NoPendingChangesets
519	            }
520	        );
521	    }
522	
523	    #[test]
524	    fn rejects_ambiguous_foreign_and_malformed_managed_prs() {
525	        let ambiguous = snapshot(vec![
526	            pr(1, "callisto/version-packages", false),
527	            pr(
528	                2,
529	                "callisto/REDACTED",
530	                false,
531	            ),
532	        ]);
533	        assert!(matches!(
534	            ReleasePrDecisionV1::derive(true, &config(), &ambiguous),
535	            Err(ReleasePrDecisionError::AmbiguousManagedPullRequests { .. })
536	        ));
537	
538	        let mut foreign = pr(1, "callisto/version-packages", false);
539	        foreign.head_repository = "fork/callisto".to_string();
540	        assert!(matches!(
541	            ReleasePrDecisionV1::derive(true, &config(), &snapshot(vec![foreign])),
542	            Err(ReleasePrDecisionError::ForeignManagedPullRequest { .. })
543	        ));
544	
545	        assert!(matches!(
546	            ReleasePrDecisionV1::derive(
547	                true,
548	                &config(),
549	                &snapshot(vec![pr(1, "callisto/version-packages--bad", false)])
550	            ),
551	            Err(ReleasePrDecisionError::MalformedManagedBranch { .. })
552	        ));
553	    }
554	
555	    #[test]
556	    fn deserialization_rejects_unknown_fields_and_schema_mismatch() {
557	        let unknown = r#"{\"schemaVersion\":1,\"repository\":\"orin-dx/callisto\",\"baseBranch\":\"main\",\"releaseBranch\":\"callisto/version-packages\",\"unexpected\":true}"#;
558	        assert!(serde_json::from_str::<ReleasePrConfigV1>(unknown).is_err());
559	        let version = r#"{\"schemaVersion\":2,\"repository\":\"orin-dx/callisto\",\"baseBranch\":\"main\",\"releaseBranch\":\"callisto/version-packages\"}"#;
560	        assert!(serde_json::from_str::<ReleasePrConfigV1>(version).is_err());
561	    }
562	
563	    #[test]
564	    fn snapshot_recheck_is_order_independent_but_rejects_a_race() {
565	        let decision = ReleasePrDecisionV1::derive(
566	            true,
567	            &config(),
568	            &snapshot(vec![pr(42, "callisto/version-packages", false)]),
569	        )
570	        .unwrap();
571	        let same = snapshot(vec![pr(42, "callisto/version-packages", false)]);
572	        assert!(decision.verify_snapshot(&same).is_ok());
573	        let changed = snapshot(vec![pr(43, "callisto/version-packages", false)]);
574	        assert!(matches!(
575	            decision.verify_snapshot(&changed),
576	            Err(ReleasePrDecisionError::SnapshotChanged)
577	        ));
578	    }
579	}
